package run.halo.starter;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.junit.jupiter.api.Test;
import reactor.core.publisher.Mono;
import run.halo.app.extension.*;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;
class OfficialAccountConfigTest {
 private final String id="wx1234567890abcdef";
 private OfficialAccountConfig.Input input(boolean publish,boolean confirmed,String app,String secret){return new OfficialAccountConfig.Input(true,true,publish,confirmed,app,secret,"小染","","");}
 @Test void defaultsDisabledAndPublishRequiresExplicitConsent(){var defaults=OfficialAccountConfig.defaults();assertFalse(defaults.isEnabled());assertFalse(defaults.isAutoSync());assertFalse(defaults.isAutoPublish());assertThrows(IllegalArgumentException.class,()->OfficialAccountConfig.validate(input(true,false,id,"secret")));assertDoesNotThrow(()->OfficialAccountConfig.validate(input(true,true,id,"secret")));assertThrows(IllegalArgumentException.class,()->OfficialAccountConfig.validate(input(false,false,"bad-id","secret")));}
 @Test void secretIsNeverReturnedAndBlankPreservesCredential(){var client=mock(ReactiveExtensionClient.class);var settings=OfficialAccountConfig.defaults();settings.setEnabled(true);settings.setAppId(id);settings.getMetadata().setVersion(1L);var sec=new Secret();sec.setMetadata(OfficialAccountConfig.metadata(OfficialAccountConfig.NAME));sec.getMetadata().setVersion(1L);sec.setData(Map.of("appSecret","private-value".getBytes(StandardCharsets.UTF_8)));when(client.fetch(OfficialAccountSettings.class,OfficialAccountConfig.NAME)).thenReturn(Mono.just(settings));when(client.fetch(Secret.class,OfficialAccountConfig.NAME)).thenReturn(Mono.just(sec));when(client.update(settings)).thenReturn(Mono.just(settings));var config=new OfficialAccountConfig(client);var result=config.save(input(false,false,id,"")).block();assertEquals(true,result.get("hasSecret"));assertFalse(result.toString().contains("private-value"));verify(client,never()).update(any(Secret.class));assertEquals("private-value",config.credentials(id).block().secret());assertFalse(config.credentials(id).block().toString().contains("private-value"));assertFalse(input(false,false,id,"private-value").toString().contains("private-value"));}
 @Test void switchingAccountRequiresNewSecret(){var client=mock(ReactiveExtensionClient.class);var settings=OfficialAccountConfig.defaults();settings.setAppId(id);var sec=new Secret();sec.setData(Map.of("appSecret","private-value".getBytes(StandardCharsets.UTF_8)));when(client.fetch(OfficialAccountSettings.class,OfficialAccountConfig.NAME)).thenReturn(Mono.just(settings));when(client.fetch(Secret.class,OfficialAccountConfig.NAME)).thenReturn(Mono.just(sec));var config=new OfficialAccountConfig(client);assertThrows(IllegalArgumentException.class,()->config.save(input(false,false,"wxabcdef1234567890","")).block());verify(client,never()).create(any(OfficialAccountSettings.class));}
 @Test void fieldErrorsIdentifyAppIdRatherThanBlamingValidAuthor(){var error=assertThrows(IllegalArgumentException.class,()->OfficialAccountConfig.validate(input(false,false,"wx3b30bc019c1e81d","secret")));assertTrue(error.getMessage().contains("AppID"));assertTrue(error.getMessage().contains("17"));assertFalse(error.getMessage().contains("作者"));assertDoesNotThrow(()->OfficialAccountConfig.validate(input(false,false,id,"secret")));var authorError=assertThrows(IllegalArgumentException.class,()->OfficialAccountConfig.validate(new OfficialAccountConfig.Input(true,true,false,false,id,"secret","名字超过八个汉字了","","")));assertTrue(authorError.getMessage().contains("署名"));}
}
